/* TrailScope module: ui.js — generated by JS modularization build. */
function updatePaginationControls() {
    const totalPages = Math.ceil(totalSegments / pageSize);

    document.getElementById('pageInfo').textContent = `Page ${currentPage}/${totalPages}`;

    document.getElementById('firstPageBtn').disabled = currentPage === 1;
    document.getElementById('prevPageBtn').disabled = currentPage === 1;
    document.getElementById('nextPageBtn').disabled = currentPage === totalPages;
    document.getElementById('lastPageBtn').disabled = currentPage === totalPages;

    document.getElementById('pageSizeInfo').innerHTML = ` sections in a page, ${totalSegments} total`;

    const pageSizeSelect = document.getElementById('pageSizeSelect');
    const currentValue = pageSizeSelect.value;

    pageSizeSelect.innerHTML = '';

    const baseOptions = [10, 20, 25, 50, 100, 200, 250, 500, 1000];

    baseOptions.forEach(opt => {
        if (opt <= totalSegments || opt === 10) {
            const option = document.createElement('option');
            option.value = opt;
            option.textContent = opt;
            pageSizeSelect.appendChild(option);
        }
    });

    const allOption = document.createElement('option');
    allOption.value = totalSegments;
    allOption.textContent = 'All';
    pageSizeSelect.appendChild(allOption);

    let valueToSet = currentValue;
    let found = false;
    for (let i = 0; i < pageSizeSelect.options.length; i++) {
        if (pageSizeSelect.options[i].value === currentValue) {
            found = true;
            break;
        }
    }
    if (!found) {
        valueToSet = pageSizeSelect.options[0] ? pageSizeSelect.options[0].value : '10';
    }
    pageSizeSelect.value = valueToSet;

    pageSize = parseInt(pageSizeSelect.value);
}
